<script setup lang="ts">
import { ref } from 'vue'
import { useRouter, RouterLink } from 'vue-router'
import { ArrowLeft, ArrowRight, Eye, EyeOff, LockKeyhole, ShieldCheck, Sparkles } from 'lucide-vue-next'
import { loginAccount } from '../services/auth'
import { loginSystemAdmin } from '../services/systemAdmin'

const router=useRouter(),email=ref(''),password=ref(''),show=ref(false),loading=ref(false),error=ref('')
async function login(){
  loading.value=true;error.value=''
  try{await loginSystemAdmin(email.value.trim(),password.value);await loginAccount(email.value.trim(),password.value);router.push('/yonetim')}
  catch(e){error.value=e instanceof Error?e.message:'Giriş yapılamadı'}finally{loading.value=false}
}
</script>

<template><div class="manager-login">
  <div class="orb orb-one"></div><div class="orb orb-two"></div>
  <RouterLink to="/giris" class="back"><ArrowLeft :size="16"/> İşletme girişine dön</RouterLink>
  <main>
    <section class="manager-story"><span class="eyebrow"><Sparkles :size="14"/> YENİ NESİL KONTROL</span><h1>İşletmeni<br/><em>tek bakışta</em> yönet.</h1><p>Yayın durumundan QR trafiğine kadar bütün operasyon, sade ve güvenli bir merkezde.</p><div class="trust"><ShieldCheck :size="22"/><div><strong>Güvenli yönetici alanı</strong><small>Yetkilendirilmiş erişim ve hareket kayıtları</small></div></div></section>
    <section class="manager-card"><div class="icon"><LockKeyhole :size="23"/></div><span class="label">YÖNETİCİ PORTALI</span><h2>Kontrol merkezine giriş</h2><p>Yönetici bilgilerinizle devam edin.</p><form @submit.prevent="login"><label>E-posta<input v-model="email" type="email" placeholder="yonetici@firma.com" autocomplete="username" required/></label><label>Şifre<div class="password"><input v-model="password" :type="show?'text':'password'" placeholder="Şifrenizi girin" autocomplete="current-password" required/><button type="button" @click="show=!show"><EyeOff v-if="show" :size="18"/><Eye v-else :size="18"/></button></div></label><p v-if="error" class="error">{{error}}</p><button class="submit" :disabled="loading">{{loading?'Doğrulanıyor...':'Güvenli giriş'}}<ArrowRight :size="18"/></button></form><small class="secure"><ShieldCheck :size="13"/> Bağlantınız güvenli olarak doğrulanır</small></section>
  </main>
</div></template>

